questions.starter:
function labeledInput(id, labelText, name) {
  // return markup
}

questions.solution:
function labeledInput(id, labelText, name) {
  return '<label for="' + id + '">' + labelText + '</label><input id="' + id + '" type="text" name="' + name + '" />';
}

questions.starter:
function imgAlt(src, alt, decorative) {
  // return markup
}

questions.solution:
function imgAlt(src, alt, decorative) {
  const text = decorative ? '' : alt;
  return '<img src="' + src + '" alt="' + text + '" />';
}
